using Dapper;
using SubscriptionPlatform.Api.Data;
using SubscriptionPlatform.Api.Models;

namespace SubscriptionPlatform.Api.Repositories;

public sealed class SubscriptionRepository(ConnectionFactory connections)
{
    public sealed record OrderData(Guid SubscriptionId,Guid PaymentId,string Status,long Amount,string Currency);
    public async Task<OrderData?> CreateAsync(Guid appId,CreateSubscriptionRequest r){await using var db=connections.Create();await db.OpenAsync();await using var tx=await db.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var customer=await db.ExecuteScalarAsync<Guid?>("SELECT id FROM customers WHERE id=@CustomerId AND application_id=@appId FOR UPDATE",new{r.CustomerId,appId},tx);var plan=await db.QuerySingleOrDefaultAsync<dynamic>("SELECT currency,monthly_amount_minor,yearly_amount_minor,trial_days FROM plans WHERE id=@PlanId AND application_id=@appId AND active=1",new{r.PlanId,appId},tx);if(customer is null||plan is null)return null;var prior=await db.QuerySingleOrDefaultAsync<dynamic>("SELECT id,subscription_id,status,amount_minor,currency FROM payments WHERE idempotency_key=@key",new{key=r.IdempotencyKey},tx);if(prior is not null)return new((Guid)prior.subscription_id,(Guid)prior.id,(string)prior.status,(long)prior.amount_minor,(string)prior.currency);if(await db.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM subscriptions WHERE customer_id=@customerId AND status NOT IN ('expired','cancelled')",new{customerId=r.CustomerId},tx)>0)throw new InvalidOperationException("Customer already has a current subscription.");var priorSubs=await db.ExecuteScalarAsync<int>("SELECT COUNT(*) FROM subscriptions WHERE customer_id=@customerId",new{customerId=r.CustomerId},tx);var days=(int)plan.trial_days;if(r.StartTrial&&(days==0||priorSubs>0))throw new InvalidOperationException("Trial is not eligible.");var sid=Guid.NewGuid();var pid=Guid.NewGuid();var amount=r.BillingPeriod=="yearly"?(long)plan.yearly_amount_minor:(long)plan.monthly_amount_minor;var currency=(string)plan.currency;var now=DateTime.UtcNow;var status=r.StartTrial?"trialing":"pending_payment";var ends=r.StartTrial?(r.BillingPeriod=="yearly"?now.AddDays(days).AddYears(1):now.AddDays(days).AddMonths(1)):now;await db.ExecuteAsync("INSERT INTO subscriptions(id,application_id,customer_id,plan_id,status,billing_period,starts_utc,ends_utc,version,created_utc) VALUES(@sid,@appId,@CustomerId,@PlanId,@status,@BillingPeriod,@now,@ends,0,@now)",new{sid,appId,r.CustomerId,r.PlanId,status,r.BillingPeriod,now,ends},tx);if(r.StartTrial){await db.ExecuteAsync("INSERT INTO subscription_audits(subscription_id,from_status,to_status,reason,at_utc) VALUES(@sid,'new','trialing','eligible_trial_started',@now)",new{sid,now},tx);await tx.CommitAsync();return new(sid,Guid.Empty,status,0,currency);}await db.ExecuteAsync("INSERT INTO payments(id,subscription_id,idempotency_key,amount_minor,currency,status,created_utc) VALUES(@pid,@sid,@key,@amount,@currency,'order_pending',@now)",new{pid,sid,key=r.IdempotencyKey,amount,currency,now},tx);await tx.CommitAsync();return new(sid,pid,status,amount,currency);}
    public async Task SetOrderAsync(Guid paymentId,string orderId){await using var db=connections.Create();await db.ExecuteAsync("UPDATE payments SET razorpay_order_id=@orderId WHERE id=@paymentId",new{paymentId,orderId});}
    public async Task MarkOrderFailedAsync(Guid paymentId){await using var db=connections.Create();await db.ExecuteAsync("UPDATE payments SET status='order_failed' WHERE id=@paymentId",new{paymentId});}
    public async Task<object?> GetAsync(Guid id,Guid appId){await using var db=connections.Create();return await db.QuerySingleOrDefaultAsync("SELECT s.*,p.name plan_name FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.id=@id AND s.application_id=@appId",new{id,appId});}
    public async Task<bool> CancelAsync(Guid id,Guid appId){await using var db=connections.Create();return await db.ExecuteAsync("UPDATE subscriptions SET cancel_at_period_end=1,version=version+1 WHERE id=@id AND application_id=@appId AND status IN ('active','trialing')",new{id,appId})>0;}
    public async Task<bool> ChangePlanAsync(Guid id,Guid appId,Guid planId){await using var db=connections.Create();return await db.ExecuteAsync("UPDATE subscriptions s JOIN plans p ON p.id=@planId AND p.application_id=@appId AND p.active=1 SET s.plan_id=p.id,s.version=s.version+1 WHERE s.id=@id AND s.application_id=@appId AND s.status IN ('active','trialing')",new{id,planId,appId})>0;}
}
